Given the head of a linked list, delete the last node of the given linked list.Examples:  Input: Output:  Explanation: The last node of the linked list is 5, so 5 is deleted. Input:  Output: 3 -> 12 -> NULL  Explanation: The last node of the linked list is 15, so 15 is deleted.  Try It YourselfApproach: To perform the deletion operation at the end of linked list, we need to traverse the list to find the second last node, then set its next pointer to null. If the list is empty then there is no node to delete or has only one node then point head to null.Step-by-step approach:Check if list is empty then return NULL.If the list has only one node then delete it and return NULL.Traverse the list to find the second last node.=> Set the next pointer of second last node to NULL.Implementation:  
            C++

    #include <iostream>
using namespace std;

// Node class for the linked list
class Node {
public:
    int data;
    Node* next;

    Node(int x) {
        this->data = x;
        this->next = nullptr;
    }
};

// Function to remove the last node
// of the linked list
Node* removeLastNode(Node* head) {
    // If the list is empty, return nullptr
    if (head == nullptr) {
        return nullptr;
    }

    // If the list has only one node, delete it and return nullptr
    if (head->next == nullptr) {
        delete head;
        return nullptr;
    }

    // Find the second last node
    Node* secondLast = head;
    while (secondLast->next->next != nullptr) {
        secondLast = secondLast->next;
    }

    // Delete the last node
    delete secondLast->next;

    // Change next of second last
    secondLast->next = nullptr;

    return head;
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " -> ";
        head = head->next;
    }
    cout << "nullptr" << endl;
}

int main() {
    // Creating a static linked list
    // 1 -> 2 -> 3 -> 4 -> 5 -> nullptr
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);


    // Removing the last node
    head = removeLastNode(head);

    printList(head);

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// Node structure for the linked list
struct Node
{
    int data;
    struct Node *next;
};

// Function to create a new node
struct Node *createNode(int x)
{
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = x;
    newNode->next = NULL;
    return newNode;
}

// Function to remove the last node of the linked list
struct Node *removeLastNode(struct Node *head)
{
    // If the list is empty
    if (head == NULL)
        return NULL;

    // If the list has only one node
    if (head->next == NULL)
    {
        free(head);
        return NULL;
    }

    // Find the second last node
    struct Node *secondLast = head;
    while (secondLast->next->next != NULL)
    {
        secondLast = secondLast->next;
    }

    // Delete the last node
    free(secondLast->next);

    // Update next of second last node
    secondLast->next = NULL;

    return head;
}

// Function to print the linked list
void printList(struct Node *head)
{
    while (head != NULL)
    {
        printf("%d", head->data);
        if (head->next != NULL)
            printf(" -> ");
        head = head->next;
    }
    printf(" -> NULL\n");
}

int main()
{
    // Creating the linked list: 1 -> 2 -> 3 -> 4 -> 5
    struct Node *head = createNode(1);
    head->next = createNode(2);
    head->next->next = createNode(3);
    head->next->next->next = createNode(4);
    head->next->next->next->next = createNode(5);

    // Remove the last node
    head = removeLastNode(head);

    // Print the updated list
    printList(head);

    return 0;
}


